          "trafficpe": "Drive"
        }
      }
    }
  ],
  "dataModelSchema": {
    "trip": {
      "statusText": {
        "type": "string",
        "description": "拼车订单的正向确认状态展示文本。",
        "sampleValue": "已确认"
      },
      "minutesToDepart": {
        "type": "number",
        "description": "距离约定出发时间剩余的分钟数。",
        "sampleValue": 15
      },
      "matchedPeople": {
        "type": "number",
        "description": "当前已匹配的拼车人数。",
        "sampleValue": 3
      },
      "matchRate": {
        "type": "number",
        "description": "当前路线顺路匹配度百分比数值。",
        "sampleValue": 92
      },
      "sharedFareYuan": {
        "type": "number",
        "description": "当前拼车预计分摊金额，单位为元。",
        "sampleValue": 18
      },
      "destinationName": {
        "type": "string",
        "description": "本次拼车目的地的短名称。",
        "sampleValue": "市民中心"
      },
      "navigationTrafficpe": {
        "type": "string",
        "description": "地图导航出行方式枚举，Drive 表示开车。",
        "sampleValue": "Drive"
      },
      "destination": {
        "latitude": {
          "type": "string",
          "description": "目的地纬度字符串，用于地图导航事件参数。",
          "sampleValue": "22.543100"
        },
        "longitude": {
          "type": "string",
          "description": "目的地经度字符串，用于地图导航事件参数。",
          "sampleValue": "114.057900"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车彩色图标，适合用于拼车出行卡片的车辆视觉锚点和图片延伸区域。"
    }
  ]
}

